style.css:
@-moz-document domain("instagram.com") {
/*==================================================
      INSTAGRAM • EMERALD NEON
==================================================*/

:root{
    --bg:#050805;
    --panel:#0b120d;
    --card:#111a13;
    --green:#00ff88;
    --green2:#00cc66;
    --border:rgba(0,255,136,.22);
    --text:#ffffff;
}

/* Background */

html,
body{
    background:
        radial-gradient(circle at top left,#06351b 0%,transparent 35%),
        radial-gradient(circle at bottom right,#031b10 0%,transparent 40%),
        linear-gradient(135deg,#030503,#071008,#030503)!important;
    color:var(--text)!important;
    font-family:system-ui,sans-serif!important;
}

/* Cards */

article,
section,
main,
header,
nav,
aside,
div[role="dialog"]{
    background:var(--card)!important;
    border:1px solid var(--border)!important;
    border-radius:16px;
}

/* Hover */

article:hover,
section:hover,
button:hover{
    border-color:var(--green)!important;
    box-shadow:
        0 0 10px rgba(0,255,136,.45),
        0 0 30px rgba(0,255,136,.18);
    transition:.25s;
}

/* Sidebar */

nav{
    background:
        linear-gradient(180deg,#102015,#071008)!important;
}

/* Links */

a{
    color:white!important;
    transition:.2s;
}

a:hover{
    color:var(--green)!important;
    text-shadow:0 0 8px #00ff88;
}

/* Buttons */

button{
    background:
        linear-gradient(135deg,#00ff88,#00cc66)!important;
    color:#031004!important;
    border:none!important;
    border-radius:12px;
    font-weight:bold;
}

button:hover{
    box-shadow:
        0 0 10px #00ff88,
        0 0 25px rgba(0,255,136,.6);
}

/* Inputs */

input,
textarea{
    background:#091109!important;
    border:1px solid var(--border)!important;
    color:white!important;
    border-radius:10px;
}

input:focus,
textarea:focus{
    border-color:var(--green)!important;
    box-shadow:0 0 12px rgba(0,255,136,.45);
}

/* Images */

img{
    border-radius:14px;
}

/* Scrollbar */

::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-track{
    background:#040604;
}

::-webkit-scrollbar-thumb{
    background:linear-gradient(#00ff88,#00b85e);
    border-radius:999px;
}

/* Selection */

::selection{
    background:#00ff88;
    color:black;
}

/* Smooth */

*{
    transition:
        background .2s,
        color .2s,
        border-color .2s,
        box-shadow .2s;
}
}
